import * as React from "react";
import { cn } from "@/lib/utils";
import { SampleButton } from "@/components/ui/sample-button";

export function SampleCard({ title, body, action, className }: { title: string; body: string; action: string; className?: string }) {
  return (
    <div data-slot="card" className={cn("flex flex-col gap-4 rounded-xl border bg-card p-6 text-card-foreground shadow-sm", className)}>
      <div className="flex flex-col gap-1.5">
        <h3 className="text-lg leading-none font-semibold">{title}</h3>
        <p className="text-sm text-muted-foreground">{body}</p>
      </div>
      <div className="flex justify-end gap-2">
        <SampleButton variant="outline" size="sm">Later</SampleButton>
        <SampleButton size="sm">{action}</SampleButton>
      </div>
    </div>
  );
}
